// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(0));
        vm.assume(callee != address(c));
        // A fuzzed address has no code, so the low-level call always succeeds.
        bool ok;
        (bool callOk, ) = address(c).call(
            abi.encodeWithSelector(c.forward.selector, callee, data)
        );
        ok = callOk;
        // Rule: forwarding to a codeless (always-succeeding) callee never reverts.
        assertTrue(ok, "forward to succeeding callee must not revert");
    }
}
